const TAU=Math.PI*2;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function hash(s){let h=2166136261;for(const c of String(s)){h^=c.charCodeAt(0);h=Math.imul(h,16777619);}return h>>>0;}
function random(seed){return()=>{seed|=0;seed=(seed+0x6D2B79F5)|0;let t=Math.imul(seed^(seed>>>15),1|seed);t=t+Math.imul(t^(t>>>7),61|t)^t;return((t^(t>>>14))>>>0)/4294967296;};}
function colorMix(hex,m){const n=parseInt(hex.slice(1),16);return `rgb(${Math.round(((n>>16)&255)*m)},${Math.round(((n>>8)&255)*m)},${Math.round((n&255)*m)})`;}
const palettes={temperate:['#193d48','#2f6d70','#598f7d','#b5b982','#c4d1bd'],garden:['#183e46','#3c7772','#6b9f75','#a8b787','#d7dbc2'],forest:['#173e42','#356b56','#6a8b58','#a7a16c','#c5caa6'],arid:['#674a3b','#a07554','#c29e70','#dec59b','#f0dcbd'],desert:['#694a3c','#a37652','#c79e69','#d7b77e','#ebd2a7'],ice:['#244056','#4c788a','#83afbc','#c4d6d6','#edf2e4'],ocean:['#183d59','#2b6581','#5c96a1','#84aea2','#d6e0cc'],volcanic:['#342e39','#5e4042','#8c5545','#c47851','#e8ac6d'],barren:['#343b47','#58616b','#7d8990','#a3ada8','#d1d4c2'],station:['#233b4a','#385560','#718d8e','#a4b4a5','#d9d6b4']};
export class SpaceRenderer{
 constructor(){this.stars=[];const rng=random(832);for(let i=0;i<450;i++)this.stars.push({x:rng(),y:rng(),size:rng()>.94?2:1,a:.2+rng()*.7,depth:.04+rng()*.13,color:rng()>.8?'#d0b486':rng()>.75?'#7aadb9':'#98b3bc'});this.planetCache=new Map();this.camera={x:0,y:0};this.particles=[];this.lastMode=null;}
 planet(body){const key=`${body.id}:${body.biome}`;if(this.planetCache.has(key))return this.planetCache.get(key);const c=document.createElement('canvas');c.width=128;c.height=128;const ctx=c.getContext('2d'),p=palettes[body.biome]??palettes.temperate,seed=hash(body.id),r=random(seed),offset=r()*100;for(let y=0;y<128;y++)for(let x=0;x<128;x++){let dx=(x-63.5)/63,dy=(y-63.5)/63,dist=dx*dx+dy*dy;if(dist>1)continue;let z=Math.sqrt(1-dist),noise=Math.sin(dx*9+offset+Math.sin(dy*8)*1.5)+Math.cos(dy*11+offset*2+dx*7)*.5+Math.sin(dx*25+dy*16+offset)*.25;const grain=r()*.3;let idx=clamp(Math.floor((noise+1.9+grain)*1.2),0,3);if(body.biome==='ice'&&Math.abs(dy)>.65)idx=4;if((body.biome==='temperate'||body.biome==='garden'||body.biome==='ocean')&&Math.sin(dx*12+dy*9+offset)+Math.sin(dy*18+offset)*.7>1.15)idx=4;const light=clamp(.2+(-dx*.65-dy*.32+z*.55)*.85,.13,1);ctx.fillStyle=colorMix(p[idx],light);ctx.fillRect(x,y,1,1);}this.planetCache.set(key,c);return c;}
 draw(ctx,game,{width:w,height:h,time=0,welcome=false,tracked=null,guidance='simple',motion=true}={}){
  const s=game.state,ship=s.ship,sys=game.system??{},mobile=w<430;ctx.imageSmoothingEnabled=false;ctx.fillStyle='#07101b';ctx.fillRect(0,0,w,h);
  const z=mobile?.50:.66;this.zoom=z;
  const targetX=ship.x+(welcome?-160:0),targetY=ship.y+(welcome?-40:0);
  if(this.lastSystem!==s.systemId){this.camera.x=targetX;this.camera.y=targetY;this.lastSystem=s.systemId;}
  this.camera.x+=(targetX-this.camera.x)*(motion?.09:1);this.camera.y+=(targetY-this.camera.y)*(motion?.09:1);
  const cx=this.camera.x,cy=this.camera.y;this.w=w;this.h=h;
  const fog=ctx.createRadialGradient(w*.7,h*.4,0,w*.7,h*.4,w*.75);fog.addColorStop(0,'#112c3645');fog.addColorStop(.4,'#142a3930');fog.addColorStop(1,'#07101b00');ctx.fillStyle=fog;ctx.fillRect(0,0,w,h);
  for(const st of this.stars){let x=((st.x*w*2-cx*st.depth)%(w*2)+w*2)%(w*2),y=((st.y*h*2-cy*st.depth)%(h*2)+h*2)%(h*2);if(x>w||y>h)continue;ctx.globalAlpha=st.a*(motion?.87+Math.sin(time*.3+st.x*45)*.13:1);ctx.fillStyle=st.color;ctx.fillRect(Math.floor(x),Math.floor(y),st.size,st.size);if(st.size===2&&st.a>.75){ctx.globalAlpha=.2;ctx.fillRect(Math.floor(x)-2,Math.floor(y)+1,6,1);ctx.fillRect(Math.floor(x)+1,Math.floor(y)-2,1,6);}}
  ctx.globalAlpha=1;
  // Sparse navigation mesh, intentionally subordinate to the world.
  ctx.strokeStyle='#31495a10';ctx.lineWidth=1;const grid=160*z;for(let x=(-cx*z+w/2)%grid;x<w;x+=grid){ctx.beginPath();ctx.moveTo(Math.round(x)+.5,0);ctx.lineTo(Math.round(x)+.5,h);ctx.stroke();}for(let y=(-cy*z+h/2)%grid;y<h;y+=grid){ctx.beginPath();ctx.moveTo(0,Math.round(y)+.5);ctx.lineTo(w,Math.round(y)+.5);ctx.stroke();}
  const to=(x,y)=>({x:Math.round((x-cx)*z+w/2),y:Math.round((y-cy)*z+h/2)});
  // A distant illuminated crescent makes the first system feel inhabited.
  const bodies=sys.bodies??[];
  for(const b of bodies){const p=to(b.x,b.y),radius=(b.radius??b.r??65)*z;if(p.x+radius*2<-50||p.x-radius*2>w+50||p.y+radius*2<-50||p.y-radius*2>h+50)continue;
   if(b.kind==='station'){drawStation(ctx,p.x,p.y,Math.max(24,radius),time,b.id);}
   else{const r=Math.max(20,radius);if(b.rings||b.biome==='arid'){ctx.save();ctx.translate(p.x,p.y);ctx.rotate(-.38);ctx.strokeStyle='#9b9a7666';ctx.lineWidth=4;ctx.beginPath();ctx.ellipse(0,0,r*1.65,r*.38,0,0,TAU);ctx.stroke();ctx.strokeStyle='#c2b98b40';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,0,r*1.85,r*.43,0,0,TAU);ctx.stroke();ctx.restore();}ctx.drawImage(this.planet(b),Math.round(p.x-r),Math.round(p.y-r),Math.round(r*2),Math.round(r*2));}
   if(!welcome){ctx.font='8px "Courier New",monospace';ctx.textAlign='center';ctx.fillStyle=b.id===tracked?'#e6cc95':'#9eb5bc';ctx.fillText(b.name,p.x,p.y+radius+19);ctx.font='5px "Courier New",monospace';ctx.fillStyle='#566e80';ctx.fillText((b.kind??'world').toUpperCase(),p.x,p.y+radius+28);}
  }
  for(const a of sys.asteroids??[]){if(a.depleted||a.hp===0||a.health===0)continue;const p=to(a.x,a.y),r=(a.radius??a.r??16)*z;if(p.x<-r||p.x>w+r||p.y<-r||p.y>h+r)continue;drawAsteroid(ctx,p.x,p.y,r,a.seed??hash(a.id),a.type??a.resource);}
  for(const p0 of sys.pickups??[]){const p=to(p0.x,p0.y);ctx.fillStyle=p0.type==='ore'?'#d4bc84':'#8ac9c4';ctx.fillRect(p.x-2,p.y-2,5,5);ctx.fillStyle='#5f7e8155';ctx.fillRect(p.x-4,p.y-4,9,1);}
  for(const sig of sys.signals??[]){if(sig.resolved)continue;const p=to(sig.x,sig.y);if(p.x<0||p.x>w||p.y<0||p.y>h)continue;const a=motion?(Math.sin(time*2)+1)/2:.5;ctx.strokeStyle='#85c5bd';ctx.globalAlpha=.25+a*.4;ctx.beginPath();ctx.arc(p.x,p.y,12+a*9,0,TAU);ctx.stroke();ctx.globalAlpha=1;ctx.fillStyle='#b6d6cf';ctx.fillRect(p.x-2,p.y-2,4,4);ctx.font='6px "Courier New",monospace';ctx.textAlign='center';ctx.fillStyle='#829f9f';ctx.fillText(sig.name??'UNIDENTIFIED SIGNAL',p.x,p.y+31);}
  for(const t of sys.traffic??[]){const p=to(t.x,t.y);drawShip(ctx,p.x,p.y,t.angle??0,'#8498a0',.7,Boolean(t.vx||t.vy),time);}
  for(const e of sys.enemies??[]){if(e.hull<=0||e.hp<=0||e.dead)continue;const p=to(e.x,e.y);drawShip(ctx,p.x,p.y,e.angle??0,e.hostile===false?'#819ea5':'#c7806b',.85,true,time);if(!welcome){ctx.fillStyle='#5b3939';ctx.fillRect(p.x-12,p.y-22,24,2);ctx.fillStyle='#d28a70';ctx.fillRect(p.x-12,p.y-22,24*clamp((e.hull??e.hp??30)/(e.maxHull??e.maxHp??30),0,1),2);}}
  for(const b of sys.bullets??[]){const p=to(b.x,b.y);ctx.strokeStyle=b.owner==='player'||b.friendly?'#e6d99a':'#e79577';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x-(b.vx??Math.cos(b.angle??0)*400)*.014*z,p.y-(b.vy??Math.sin(b.angle??0)*400)*.014*z);ctx.stroke();}
  const sp=to(ship.x,ship.y),speed=Math.hypot(ship.vx??0,ship.vy??0);
  if(ship.miningTarget||sys.miningTarget||game.miningTarget){let a=ship.miningTarget??sys.miningTarget??game.miningTarget;if(typeof a==='string')a=(sys.asteroids??[]).find(x=>x.id===a);if(a){const p=to(a.x,a.y);ctx.strokeStyle='#87e7d488';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(sp.x,sp.y);ctx.lineTo(p.x,p.y);ctx.stroke();ctx.strokeStyle='#dcffe4';ctx.lineWidth=1;ctx.stroke();}}
  drawShip(ctx,sp.x,sp.y,ship.angle??0,'#c5d4c9',1,speed>12,time,ship.boosting);
  if((ship.shield??0)>0){ctx.strokeStyle='#80c6ce20';ctx.lineWidth=1;ctx.beginPath();ctx.arc(sp.x,sp.y,23,0,TAU);ctx.stroke();}
  if(!welcome&&guidance!=='expert'){const b=[...bodies,...(sys.signals??[]),...(sys.asteroids??[]),...(sys.enemies??[])].find(b=>b.id===tracked);if(b){const p=to(b.x,b.y),d=Math.hypot(b.x-ship.x,b.y-ship.y);if(p.x<25||p.x>w-25||p.y<35||p.y>h-65){const dx=p.x-sp.x,dy=p.y-sp.y,angle=Math.atan2(dy,dx),ex=clamp(sp.x+dx,23,w-23),ey=clamp(sp.y+dy,55,h-80);ctx.save();ctx.translate(ex,ey);ctx.rotate(angle);ctx.fillStyle='#dfc68f';ctx.beginPath();ctx.moveTo(6,0);ctx.lineTo(-4,-4);ctx.lineTo(-4,4);ctx.fill();ctx.restore();ctx.font='7px "Courier New",monospace';ctx.fillStyle='#d9c28e';ctx.textAlign=ex>w/2?'right':'left';ctx.fillText(`${b.name??'Mining belt'} · ${Math.round(d)}m`,clamp(ex+(ex>w/2?-10:10),80,w-80),ey+3);}}}
  if(s.jumpFlash>0){ctx.fillStyle=`rgba(169,225,214,${Math.min(.5,s.jumpFlash*.3)})`;ctx.fillRect(0,0,w,h);}
 }
 toWorld(x,y){return{x:(x-this.w/2)/this.zoom+this.camera.x,y:(y-this.h/2)/this.zoom+this.camera.y};}
 radar(ctx,game,tracked){const w=ctx.canvas.width,h=ctx.canvas.height,s=game.state.ship,sys=game.system??{};ctx.clearRect(0,0,w,h);const cx=w/2,cy=h/2,r=Math.min(w,h)/2-8;ctx.strokeStyle='#2e4b5666';ctx.lineWidth=1;for(const n of [.3,.65,1]){ctx.beginPath();ctx.arc(cx,cy,r*n,0,TAU);ctx.stroke();}ctx.beginPath();ctx.moveTo(cx-r,cy);ctx.lineTo(cx+r,cy);ctx.moveTo(cx,cy-r);ctx.lineTo(cx,cy+r);ctx.stroke();const scale=r/1900;const dot=(x,y,col,size=3)=>{const px=cx+(x-s.x)*scale,py=cy+(y-s.y)*scale;if(Math.hypot(px-cx,py-cy)>r)return;ctx.fillStyle=col;ctx.fillRect(Math.round(px-size/2),Math.round(py-size/2),size,size);};for(const a of sys.asteroids??[])if(!a.depleted)dot(a.x,a.y,'#536768',2);for(const b of sys.bodies??[])dot(b.x,b.y,b.id===tracked?'#ebcf99':'#8bbfb5',b.kind==='station'?5:7);for(const e of sys.enemies??[])if(!e.dead)dot(e.x,e.y,'#db8870',4);for(const p of sys.signals??[])if(!p.resolved)dot(p.x,p.y,'#aab5d3',4);ctx.save();ctx.translate(cx,cy);ctx.rotate(s.angle??0);ctx.fillStyle='#eee6c4';ctx.beginPath();ctx.moveTo(6,0);ctx.lineTo(-4,-3);ctx.lineTo(-2,0);ctx.lineTo(-4,3);ctx.fill();ctx.restore();}
}
export function drawShip(ctx,x,y,angle=0,color='#c5d4c9',scale=1,thrust=false,time=0,boost=false){ctx.save();ctx.translate(Math.round(x),Math.round(y));ctx.rotate(angle);ctx.scale(scale,scale);if(thrust){const l=(boost?20:10)+Math.sin(time*38)*3;ctx.fillStyle=boost?'#82c9c1':'#d29a63';ctx.fillRect(-18-l,-3,l,6);ctx.fillStyle=boost?'#d2f0db':'#eed2a0';ctx.fillRect(-18-l*.55,-2,l*.55,4);ctx.fillStyle='#65c1c944';ctx.fillRect(-18-l*1.2,-4,l*.5,8);}ctx.fillStyle='#101e29';ctx.fillRect(-17,-10,20,20);ctx.fillStyle='#475965';ctx.fillRect(-14,-13,13,7);ctx.fillRect(-14,6,13,7);ctx.fillStyle=color;ctx.fillRect(-14,-11,9,4);ctx.fillRect(-14,7,9,4);ctx.fillRect(-9,-6,20,12);ctx.fillRect(11,-4,5,8);ctx.fillRect(16,-2,4,4);ctx.fillStyle='#8a9c9f';ctx.fillRect(-15,-4,8,8);ctx.fillStyle='#172c3c';ctx.fillRect(3,-3,7,6);ctx.fillStyle='#79bbc0';ctx.fillRect(5,-2,4,3);ctx.fillStyle='#e0c592';ctx.fillRect(-10,-10,2,2);ctx.fillRect(-10,8,2,2);ctx.fillStyle='#243747';ctx.fillRect(-18,-5,3,10);ctx.restore();}
function drawStation(ctx,x,y,r,time,id){const z=Math.max(.65,r/55);ctx.save();ctx.translate(Math.round(x),Math.round(y));ctx.scale(z,z);ctx.fillStyle='#182c3b';ctx.fillRect(-47,-17,94,34);ctx.fillRect(-17,-47,34,94);ctx.strokeStyle='#48616c';ctx.lineWidth=2;ctx.strokeRect(-43,-15,86,30);ctx.strokeRect(-15,-43,30,86);ctx.fillStyle='#39525e';for(const k of [-1,1]){ctx.fillRect(k<0?-66:40,-27,26,54);ctx.fillRect(-27,k<0?-66:40,54,26);ctx.fillStyle='#294651';ctx.fillRect(k<0?-62:44,-22,18,44);ctx.fillRect(-22,k<0?-62:44,44,18);ctx.fillStyle='#5a6e72';ctx.fillRect(k<0?-66:40,-27,26,3);ctx.fillRect(-27,k<0?-66:40,54,3);ctx.fillStyle='#39525e';}ctx.fillStyle='#567376';ctx.fillRect(-23,-23,46,46);ctx.fillStyle='#172f3b';ctx.fillRect(-19,-19,38,38);ctx.fillStyle='#87b9ad';ctx.fillRect(-10,-10,20,20);ctx.fillStyle='#537f7f';ctx.fillRect(-7,-7,14,14);ctx.fillStyle='#0a2435';ctx.fillRect(-3,-3,6,6);ctx.fillStyle='#cbbe8b';for(const v of [-50,-42,42,50]){ctx.fillRect(v,-21,3,3);ctx.fillRect(v,18,3,3);ctx.fillRect(-21,v,3,3);ctx.fillRect(18,v,3,3);}ctx.strokeStyle='#42636f';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,-66);ctx.lineTo(0,-82);ctx.moveTo(-7,-77);ctx.lineTo(7,-77);ctx.stroke();ctx.fillStyle=Math.sin(time*2)>0?'#e0b57a':'#7c674e';ctx.fillRect(-1,-84,3,3);ctx.strokeStyle='#9cc6ae55';ctx.setLineDash([3,4]);ctx.strokeRect(40,35,42,31);ctx.setLineDash([]);ctx.font='5px "Courier New",monospace';ctx.fillStyle='#9eb8a7';ctx.textAlign='center';ctx.fillText('DOCK',61,53);ctx.restore();}
function drawAsteroid(ctx,x,y,r,seed,type){const rng=random(seed);ctx.save();ctx.translate(Math.round(x),Math.round(y));ctx.fillStyle=type==='crystal'?'#34565b':'#51565a';ctx.beginPath();for(let i=0;i<8;i++){const a=i/8*TAU,v=r*(.75+rng()*.3),px=Math.round(Math.cos(a)*v),py=Math.round(Math.sin(a)*v);i?ctx.lineTo(px,py):ctx.moveTo(px,py);}ctx.closePath();ctx.fill();ctx.fillStyle=type==='crystal'?'#77b8aa':'#798078';ctx.fillRect(-r*.4,-r*.5,Math.max(2,r*.6),Math.max(2,r*.18));ctx.fillStyle='#2d3c43';ctx.fillRect(r*.13,r*.12,Math.max(2,r*.3),Math.max(2,r*.25));if(type==='crystal'){ctx.fillStyle='#b7dfce';ctx.fillRect(-2,-2,3,4);}ctx.restore();}
